/// <summary>
/// Khóa tự động các ca thi quá hạn nhập điểm (CT đến ngày + số ngày ân hạn).
/// </summary>
private int AutoLockByGraceDays()
{
    try
    {
        if (!uExamDate.YearSemesterEditor.IsValidData())
        {
            MessageManager.Warning("Vui lòng chọn niên khóa và học kỳ trước khi khóa ca thi!");
            return -1;
        }

        int intGraceDays = GetGraceDaysValue();
        if (intGraceDays < 0)
        {
            MessageManager.Warning("Số ngày khóa không hợp lệ!");
            return -1;
        }

        SIM_TestSchedule obj = new SIM_TestSchedule();
        System.Data.DataTable dtb = obj.GetDataTable("SIM_TestSchedule_AutoLockByExamMarkDate",
                                        "@GraceDays", intGraceDays,
                                        "@YearID", uExamDate.YearSemesterEditor.YearIDEditValue,
                                        "@Semester", uExamDate.YearSemesterEditor.SemesterEditValue,
                                        "@ExamDateID", uExamDate.ExamDateID,
                                        "@UpdatedUser", UserSession.Username);

        if (dtb == null || dtb.Rows.Count == 0)
        {
            MessageManager.Error("Việc khóa ca thi tự động bị lỗi!");
            return -1;
        }

        return Convert.ToInt32(dtb.Rows[0]["LockedCount"]);
    }
    catch (Exception objExc)
    {
        MessageManager.Error("Việc khóa ca thi tự động bị lỗi!");
        return -1;
    }
}

