private void btnSave_Click(object sender, EventArgs e)
{
    if (!HasPendingSave())
        return;

    if (MessageManager.Confirm("Bạn có thực sự muốn lưu những thay đổi dữ liệu này?") != DialogResult.Yes)
        return;

    bool bolHasGridEdit = HasPendingGridEdit();

    if (bolHasGridEdit)
    {
        if (!SaveData())
            return;
    }

    int intLockCount = AutoLockByGraceDays();
    if (intLockCount < 0)
        return;

    intGraceDaysSaved = GetGraceDaysValue();
    bolGraceDaysChanged = false;
    SetSaveButtonEnabled(false);

    if (!bolHasGridEdit)
    {
        if (intLockCount > 0)
            MessageManager.Info(String.Format("Đã khóa {0} ca quá hạn nhập điểm.", intLockCount));
        else
            MessageManager.Info("Không có ca thi nào cần khóa.");
    }
    else if (intLockCount > 0)
    {
        MessageManager.Info(String.Format("Đã tự khóa thêm {0} ca quá hạn nhập điểm.", intLockCount));
    }

    if (uExamDate.YearSemesterEditor.IsValidData())
    {
        BeginProcess();
        new Thread(LoadData).Start();
    }
}

